style.css:
@-moz-document domain("chat.qwen.ai") {
html::before {
    content: "";
    position: fixed;
    inset: 0;
    z-index: 0;
    background-image: url("https://cdn.discordapp.com/attachments/1452943520271962236/1494958711284957295/Pudding_a_la_mode_gacha_background.png?ex=69e5290b&is=69e3d78b&hm=5318e25f25555853ac67935791d3f19dd5fa817efd566ed42884eea7472ed91e");
    background-size: cover;
    background-position: center;
    background-repeat: no-repeat;
    pointer-events: none;
  }

  html, body,
  #root, .app,
  [class*="home-page"],
  [class*="layout"],
  [class*="container"],
  [class*="sidebar"],
  [class*="header"] {
    background: transparent !important;
    background-color: transparent !important;
  }

  :root {
    --container-primary-bgweb: transparent !important;
    --container-primary-bgapp: transparent !important;
    --container-primary-fill: transparent !important;
    --container-secondary-fill: transparent !important;
    --character-primary-text: #ffffff !important;
    --character-secondary-text: #ffffff !important;
    --character-tertiary-text: #ffffffcc !important;
    --character-quaternary-text: #ffffffaa !important;
    --btn-ghost-text: #ffffff !important;
    --btn-link-text: #ffffff !important;
  }

  * {
    color: #ffffff !important;
    text-shadow: 0 1px 4px rgba(0,0,0,0.6) !important;
  }
}
